function sendMessage() {
  const userInput = document.getElementById("user-input").value;
  const outputBox = document.getElementById("chat-output");

  const reply = getReply(userInput);
  outputBox.innerText = reply;

  // Đọc bằng giọng nói
  speak(reply);
}

