function speak(text) {
  if ('speechSynthesis' in window) {
    const msg = new SpeechSynthesisUtterance(text);
    msg.lang = 'vi-VN';
    speechSynthesis.speak(msg);
  } else {
    alert("Trình duyệt của bạn không hỗ trợ giọng nói.");
  }
}

